  useEffect(() => { fetchBuilderData(); }, []);
  const clearSavedState = () => { localStorage.removeItem(BUILD_STORAGE_KEY); localStorage.removeItem("trivia-flex-round-builder-state-v4"); localStorage.removeItem("trivia-flex-round-builder-state-v3"); localStorage.removeItem("trivia-flex-round-builder-state-v2"); };
  const scrollToLibrary = () => window.setTimeout(() => document.getElementById("build-session-library")?.scrollIntoView({ behavior: "smooth", block: "start" }), 50);
  const handleBrowseLibrary = () => { setUsedQuestionIds(readUsedIds()); setShowLibrary(true); setShowWriteForm(false); scrollToLibrary(); };

  const fetchBuilderData = async () => { try { setLoading(true); const [questionsResult, sessionsResult] = await Promise.all([supabase.from("questions").select("*").order("created_at", { ascending: false }), supabase.from("sessions").select("*")]); if (questionsResult.error) throw questionsResult.error; if (sessionsResult.error) throw sessionsResult.error; const localUsed = readUsedIds(); const used = new Set(); (sessionsResult.data || []).forEach((session) => collectSessionQuestions(session).forEach((question) => { const text = question?.question_text || question?.question; if (text) used.add(fingerprint(text)); })); (questionsResult.data || []).forEach((question) => { if (isQuestionMarkedUsed(question, localUsed)) used.add(fingerprint(question.question_text)); }); const prefs = loadLocalCategoryPrefs(); const approved = new Set(prefs.approved); const rejected = new Set(prefs.rejected); (questionsResult.data || []).forEach((question) => { const category = normalizeText(question.category); if (category && !rejected.has(category)) approved.add(category); }); setUsedQuestionIds(localUsed); setUsedFingerprints(used); setApprovedCategories([...approved].sort((a, b) => a.localeCompare(b))); setRejectedCategories([...rejected]); setQuestions((questionsResult.data || []).map((q) => normalizeQuestion(q))); } catch (error) { console.error("Build session load error:", error); toast.error(error.message || "Failed to load builder"); } finally { setLoading(false); } };
  const questionById = useMemo(() => new Map(questions.map((q) => [String(q.id), q])), [questions]);
  const activeRound = rounds.find((round) => round.id === activeRoundId) || rounds[0] || defaultRounds[0];
