  const activeRoundQuestions = useMemo(() => (activeRound?.questionIds || []).map((id) => questionById.get(String(id))).filter(Boolean), [activeRound, questionById]);
  const mediaQuestion = mediaQuestionId ? questionById.get(String(mediaQuestionId)) : null;
  const availableQuestions = useMemo(() => { const query = searchQuery.trim().toLowerCase(); return questions.filter((question) => { const type = normalizeType(question); const id = String(question.id); const selected = selectedIds.has(id); const used = isQuestionMarkedUsed(question, usedQuestionIds) || usedFingerprints.has(fingerprint(question.question_text)); if (typeFilter !== "all" && type !== typeFilter) return false; if (rejectedAi.has(fingerprint(question.question_text))) return false; if (used && !selected) return false; if (!query) return true; return [question.question_text, question.correct_answer, question.category, question.fun_fact].filter(Boolean).some((value) => String(value).toLowerCase().includes(query)); }); }, [questions, rejectedAi, searchQuery, selectedIds, typeFilter, usedFingerprints, usedQuestionIds]);
  const handleAddRound = () => { const round = { id: newRoundId(), name: `Round ${rounds.length + 1}`, description: "", questionIds: [] }; setRounds((prev) => [...prev, round]); setActiveRoundId(round.id); };
  const handleDeleteRound = (roundId) => { if (rounds.length === 1) return toast.error("Keep at least one round"); const nextRound = rounds.find((round) => round.id !== roundId) || rounds[0]; setRounds((prev) => prev.filter((round) => round.id !== roundId)); if (activeRoundId === roundId) setActiveRoundId(nextRound.id); };
